( LOWER(tenant_key) LIKE LOWER(CONCAT('%', #{search}, '%')) OR LOWER(plan_id) LIKE LOWER(CONCAT('%', #{search}, '%')) )
AND status = #{status}
AND tenant_key = #{tenantKey}
ORDER BY
tenant_key plan_id status updated_at created_at
ASC DESC
, id ASC LIMIT #{limit} OFFSET #{offset}

